const execution = $json.execution || {};
const workflow = $json.workflow || {};
const errorObj = execution.error || {};

const failedNode = execution.lastNodeExecuted || 'Unknown node';
const rawMessage = errorObj.message || errorObj.description || 'Unknown workflow error';
const executionUrl = execution.url || '';

const formattedError = [
  `[Node: ${failedNode}] ${rawMessage}`,
  executionUrl ? `Execution: ${executionUrl}` : null
].filter(Boolean).join(' | ');

return [{
  json: {
    workflow_name: workflow.name ?? null,
    execution_id: execution.id ?? null,
    execution_url: executionUrl,
    failed_node: failedNode,
    error_message: rawMessage,
    formatted_error: formattedError
  }
}];
